-- Migration 880: REDO of the Flock 20 import (migration 868), now with the
-- cross-flock cascade trigger disabled (migration 876), so the numeric-overflow
-- failure and cross-flock contamination cannot recur. Deletes the 2091 partially
-- inserted tagged rows first, then re-inserts the complete, correct 2391 rows.

DELETE FROM public.daily_records WHERE remarks = 'F20_IMPORT_2026-08-24';

















SELECT 'f20_import_verify' AS chk, count(*)::int AS n, sum(total_eggs)::bigint AS eggs_sum
  FROM public.daily_records WHERE remarks = 'F20_IMPORT_2026-08-24';